          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex items-start max-w-[85%] space-x-3 ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center border shadow-lg ${
                msg.role === 'user' ? 'bg-blue-600/20 border-blue-500/30' : 
                msg.role === 'assistant' ? 'bg-cyan-600/20 border-cyan-500/30' : 'bg-gray-800 border-gray-700'
              }`}>
                {msg.role === 'user' ? <User className="h-4 w-4 text-blue-400" /> : <Bot className="h-4 w-4 text-cyan-400" />}
              </div>
              <div className={`p-4 rounded-2xl shadow-xl transition-all duration-300 ${
                msg.role === 'user' ? 'bg-blue-600/10 border border-blue-500/20 text-blue-50' : 
                msg.securityEvent ? 'bg-red-500/10 border border-red-500/50 text-red-200' :
                'bg-gray-900/80 border border-gray-800 text-gray-200'
              }`}>
                <div className="flex items-center justify-between mb-2">
                   <div className="flex items-center space-x-2">
                      <span className="text-[10px] font-bold uppercase tracking-widest opacity-50">
                        {msg.role === 'user' ? 'Operator' : 'Codex Prime'}
                      </span>
                      {msg.securityEvent && (
                        <span className="text-[8px] px-1.5 py-0.5 bg-red-500/20 border border-red-500/30 text-red-400 rounded uppercase font-bold animate-pulse">
                           Boundary Violated
                        </span>
                      )}
                   </div>
                   <span className="text-[8px] font-mono opacity-30">{new Date(msg.timestamp).toLocaleTimeString()}</span>
                </div>

                {msg.image && (
                  <div className="mb-3 rounded-lg overflow-hidden border border-gray-700">
                    <img src={msg.image} alt="User upload" className="max-w-full max-h-[300px] object-contain bg-black/20" />
                  </div>
                )}

                <div className="text-sm leading-relaxed whitespace-pre-wrap font-mono">
                  {msg.content}
                </div>
              </div>
            </div>
          </div>
        ))}
        <div ref={scrollRef} />
      </div>

      <div className="p-4 bg-gray-900/50 border-t border-gray-800 backdrop-blur-md">
        {selectedImage && (
          <div className="max-w-4xl mx-auto mb-3 relative inline-block">
             <img src={selectedImage} alt="Preview" className="h-20 w-20 object-cover rounded-xl border-2 border-cyan-500/50 shadow-cyan-500/20 shadow-lg" />
             <button 
               onClick={clearImage}
               className="absolute -top-2 -right-2 p-1 bg-red-500 text-white rounded-full hover:bg-red-400 transition-colors shadow-lg"
             >
               <X className="h-3 w-3" />
             </button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="relative max-w-4xl mx-auto flex items-center space-x-2">
          <input
            type="file"
            accept="image/*"
            ref={fileInputRef}
            onChange={handleImageSelect}
            className="hidden"
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={isProcessingImage}
            className="p-3 bg-gray-950 border border-gray-800 text-gray-400 hover:text-cyan-400 hover:border-cyan-500/50 rounded-xl transition-all disabled:opacity-50"
            title="Upload Image for Analysis"
          >
            {isProcessingImage ? <Loader2 className="h-5 w-5 animate-spin" /> : <ImageIcon className="h-5 w-5" />}
          </button>

          <div className="relative flex-1">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder={selectedImage ? "Describe what to analyze in this image..." : "Input instructions for Codex Prime..."}
              className="w-full bg-gray-950 border border-gray-800 rounded-xl px-4 py-3.5 pr-12 text-sm text-gray-200 font-mono placeholder-gray-600 focus:outline-none focus:border-cyan-500/50 focus:ring-1 focus:ring-cyan-500/50 transition-all shadow-2xl"
            />
            <button
              type="submit"
              disabled={(!input.trim() && !selectedImage) || isProcessingImage}
              className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-cyan-600 hover:bg-cyan-500 disabled:bg-gray-800 disabled:text-gray-600 text-white rounded-lg transition-all"
            >
              <Send className="h-4 w-4" />
            </button>
          </div>
        </form>
        <div className="mt-2 text-center">
           <span className="text-[9px] text-gray-600 uppercase font-bold tracking-[0.2em]">Multimodal Panzershell 3.2 Secure Engine</span>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;
